install.replaced_managed_settings:
{
 "hooks": {
  "PreToolUse": [
   {
    "matcher": "Write|Edit|MultiEdit|NotebookEdit",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 1 --event PreToolUse --timeout 60 -- '/opt/enforce/check-indent-spaces.py'",
      "timeout": 90
     },
     {
      "type": "command",
      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 2 --event PreToolUse --timeout 60 -- '/opt/enforce/check-equal-spaces.py'",
      "timeout": 90
     },
     {
      "type": "command",
      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 3 --event PreToolUse --timeout 60 -- '/opt/enforce/check-function-names.py'",
      "timeout": 90
     },
     {
      "type": "command",
      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 4 --event PreToolUse --timeout 60 -- '/opt/enforce/check-class-names.py'",
      "timeout": 90
     }
    ]
   }
  ],
  "PostToolUse": [
   {
    "matcher": "Write|Edit|MultiEdit|NotebookEdit",
    "hooks": [
     {
      "type": "command",
