      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 7 --event PostToolUse --timeout 60 -- '/opt/enforce/check-filename-length.py'",
      "timeout": 90
     }
    ]
   }
  ],
  "Stop": [
   {
    "hooks": [
     {
      "type": "command",
      "command": "/usr/local/bin/python3.13 /opt/enforce-harness/wrap.py --hook 8 --event Stop --timeout 60 -- '/opt/enforce/check-chinese-only.py'",
      "timeout": 90
     }
    ]
   }
  ]
 }
}
